//! The data of [`POPULAR_ACTIONS`] and [`OUTDATED_POPULAR_ACTION_SPECS`], converted from the
//! reference's `popular_actions.go` at commit `011a6d1`. Do not edit it by hand: M7.4 replaces it
//! with the output of a generator (ADR 0011).

use super::{ActionInput, ActionOutput, PopularAction};

const fn input(id: &'static str, name: &'static str, required: bool) -> ActionInput {
    ActionInput {
        id,
        name,
        required,
        deprecated: false,
        deprecation_message: "",
    }
}

const fn deprecated(
    id: &'static str,
    name: &'static str,
    required: bool,
    deprecation_message: &'static str,
) -> ActionInput {
    ActionInput {
        id,
        name,
        required,
        deprecated: true,
        deprecation_message,
    }
}

const fn output(id: &'static str, name: &'static str) -> ActionOutput {
    ActionOutput { id, name }
}

